SET TERM ^ ;
CREATE TABLE TMP_IBPT
             (
             TMP_IBPT_ID INTEGER,
             TMP_IBPT_CODIGO VARCHAR(15),
             TMP_IBPT_EX VARCHAR(5),
             TMP_IBPT_TIPO VARCHAR(5),
             TMP_IBPT_DESCRICAO VARCHAR(2000),
             TMP_IBPT_NACIONAL NUMERIC(18,4),
             TMP_IBPT_IMPORTADO NUMERIC(18,4),
             TMP_IBPT_ESTADUAL NUMERIC(18,4),
             TMP_IBPT_MUNICIPAL NUMERIC(18,4),
             TMP_IBPT_VIGENCIA_INICIO DATE,
             TMP_IBPT_VIGENCIA_FIM DATE,
             TMP_IBPT_CHAVE VARCHAR(10),
             TMP_IBPT_VERSAO VARCHAR(10),
             TMP_IBPT_FONTE VARCHAR(30),
             TMP_IBPT_DTCAD DATE,
             TMP_IBPT_OBS VARCHAR(2000)
             );
^
SET TERM; ^

COMMIT WORK;

