SET TERM ^ ;
UPDATE EMP_PRODUTO P
SET P.PRD_NCM_ID = (
                    SELECT I.TMP_IBPT_ID
                    FROM TMP_IBPT I
                    WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                          (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                          (I.TMP_IBPT_EX IS NULL)
                   ),
    P.PRD_NCM = (
                 SELECT I.TMP_IBPT_CODIGO
                 FROM TMP_IBPT I
                 WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                       (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                       (I.TMP_IBPT_EX IS NULL)
                ),
    P.PRD_NCM_PRCFEDERAL = (
                            SELECT I.TMP_IBPT_NACIONAL
                            FROM TMP_IBPT I
                            WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                                  (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                                  (I.TMP_IBPT_EX IS NULL)
                           ),
    P.PRD_NCM_PRCESTADUAL = (
                             SELECT I.TMP_IBPT_ESTADUAL
                             FROM TMP_IBPT I
                             WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                                   (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                                   (I.TMP_IBPT_EX IS NULL)
                            ),
    P.PRD_NCM_PRCMUNICIPAL = (
                              SELECT I.TMP_IBPT_MUNICIPAL
                              FROM TMP_IBPT I
                              WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                                    (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                                    (I.TMP_IBPT_EX IS NULL)
                             ),
    P.PRD_NCM_PRCEXTRANGEIRO = (
                                SELECT I.TMP_IBPT_IMPORTADO
                                FROM TMP_IBPT I
                                WHERE ((P.PRD_NCM = I.TMP_IBPT_CODIGO) OR
                                      (0||P.PRD_NCM = I.TMP_IBPT_CODIGO)) AND
                                      (I.TMP_IBPT_EX IS NULL)
                               )
^
SET TERM; ^

COMMIT WORK;

SET TERM ^ ;
UPDATE EMP_PRODUTO P
SET P.PRD_NCM_ID = NULL,
    P.PRD_NCM = NULL,
    P.PRD_NCM_PRCFEDERAL = NULL,
    P.PRD_NCM_PRCESTADUAL = NULL,
    P.PRD_NCM_PRCMUNICIPAL = NULL,
    P.PRD_NCM_PRCEXTRANGEIRO = NULL
WHERE P.PRD_NCM NOT IN (
                        SELECT I.TMP_IBPT_CODIGO
                        FROM TMP_IBPT I
                       )

^
SET TERM; ^

COMMIT WORK;

SET TERM ^ ;
DELETE FROM EMP_IBPT;
^
SET TERM; ^

COMMIT WORK;

SET TERM ^ ;
ALTER SEQUENCE GEN_EMP_IBPT_ID RESTART WITH 0;
^
SET TERM; ^

COMMIT WORK;

SET TERM ^ ;
                      IBPT_EX,
                      IBPT_TIPO,
                      IBPT_DESCRICAO,
                      IBPT_NACIONAL,
                      IBPT_IMPORTADO,
                      IBPT_ESTADUAL,
                      IBPT_MUNICIPAL,
                      IBPT_VIGENCIA_INICIO,
                      IBPT_VIGENCIA_FIM,
                      IBPT_CHAVE,
                      IBPT_VERSAO,
                      IBPT_FONTE)
select TMP_IBPT_CODIGO,
       TMP_IBPT_EX,
       TMP_IBPT_TIPO,
       TMP_IBPT_DESCRICAO,
       TMP_IBPT_NACIONAL,
       TMP_IBPT_IMPORTADO,
       TMP_IBPT_ESTADUAL,
       TMP_IBPT_MUNICIPAL,
       TMP_IBPT_VIGENCIA_INICIO,
       TMP_IBPT_VIGENCIA_FIM,
       TMP_IBPT_CHAVE,
       TMP_IBPT_VERSAO,
       TMP_IBPT_FONTE
from TMP_IBPT
^
SET TERM; ^

COMMIT WORK;

SET TERM ^ ;
DROP TABLE TMP_IBPT
^
SET TERM; ^

COMMIT WORK;
